package com.bank.sibling;

import java.util.*;

public class SiblingConnector {

    public LevelNode connect(LevelNode root) {
        if (root == null) return null;
        Queue<LevelNode> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            LevelNode previous = null;                 // reset per level
            for (int i = 0; i < levelSize; i++) {
                LevelNode node = queue.poll();
                if (previous != null) previous.next = node;  // link left→right
                previous = node;
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            // last node's next stays null automatically
        }
        return root;
    }
}
