package com.bank.sibling;

import java.util.logging.Logger;

public class ConnectDemo {
    private static final Logger log = Logger.getLogger(ConnectDemo.class.getName());

    public static void main(String[] args) {
        LevelNode root = new LevelNode(1);
        root.left = new LevelNode(2);
        root.right = new LevelNode(3);
        root.left.left = new LevelNode(4);
        root.left.right = new LevelNode(5);
        root.right.left = new LevelNode(6);
        root.right.right = new LevelNode(7);

        new SiblingConnector().connect(root);

        // Walk each level via next pointers to verify connections.
        LevelNode leftmost = root;
        while (leftmost != null) {
            StringBuilder sb = new StringBuilder();
            for (LevelNode n = leftmost; n != null; n = n.next) {
                sb.append(n.id);
                sb.append(n.next != null ? " -> " : " -> null");
            }
            log.info("Level chain: " + sb);
            leftmost = leftmost.left;   // drop to next level's leftmost
        }
    }
}
